import pathlib,sys,hashlib,base64,json
sys.dont_write_bytecode=True
root=pathlib.Path('/srv/cellforge-inbox/continuous-control-v2');sys.path.insert(0,str(root/'controller'))
protected=[root/'REGISTRY.json',root/'STOP',pathlib.Path('/srv/cellforge-inbox/continuous-spatial-20261011/STOP')]
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
before={str(p):h(p) for p in protected}
namespace={'__name__':'readonly_observer'};exec(compile(base64.b64decode(source),'exact_observe_dispatch.py','exec'),namespace)
result=namespace['watch'](root,seconds=5)
after={str(p):h(p) for p in protected};assert before==after
assert result['phase']=='observation_pending' and result['last_snapshot']['phase']=='held_idle'
assert result['last_snapshot']['counts']['pending']==8 and result['last_snapshot']['counts']['cancelled']==1
print('READONLY_PRODUCTION_RESULT:'+json.dumps({'source_sha256':hashlib.sha256(base64.b64decode(source)).hexdigest(),'result':result,'before':before,'after':after,'production_unchanged':True},sort_keys=True),flush=True)
